import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Calculate effect sizes and p-values for each feature
    effects = []
    for i, fid in enumerate(feats.ids):
        x = feats.x[:, i]
        y = feats.y
        mean1 = np.mean(x[y == 1])
        mean0 = np.mean(x[y == 0])
        effect_size = mean1 - mean0

        # Welch's t-test
        group1 = x[y == 1]
        group0 = x[y == 0]
        if len(group1) > 1 and len(group0) > 1:
            t_stat, p_val = stats.ttest_ind(group1, group0, equal_var=False)
        else:
            p_val = 1.0

        effects.append((fid, effect_size, p_val))

    # Sort by absolute effect size
    effects.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates based on correlation
    kept = set()
    corr_threshold = 0.6
    correlations = {}

    # Build correlation matrix
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i < j:
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                correlations[(fid1, fid2)] = corr

    # Select drivers (causes) - top 2 with highest effect sizes
    drivers = []
    for fid, effect, pval in effects[:MAX_DRIVERS]:
        # Check if this feature is correlated with any already selected
        is_duplicate = False
        for selected_fid in drivers:
            if (selected_fid, fid) in correlations and abs(correlations[(selected_fid, fid)]) >= corr_threshold:
                is_duplicate = True
                break
            if (fid, selected_fid) in correlations and abs(correlations[(fid, selected_fid)]) >= corr_threshold:
                is_duplicate = True
                break
        if not is_duplicate:
            drivers.append(fid)

    # For logistic regression, use all features with significant effects
    columns = [fid for fid, effect, pval in effects if abs(effect) > 0.05 and pval < 0.1]

    # Check for product terms between highly correlated features
    products = []
    for fid1 in columns:
        for fid2 in columns:
            if fid1 < fid2:
                if (fid1, fid2) in correlations and abs(correlations[(fid1, fid2)]) >= 0.6:
                    products.append((fid1, fid2))

    # Create loadings for weighted score (use top features)
    loadings = {}
    for i, fid in enumerate(columns[:5]):  # Top 5 features for weighted score
        # Use effect size as weight
        for f, effect, _ in effects:
            if f == fid:
                loadings[fid] = effect
                break

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

